begin;
set local search_path=public,extensions;
select plan(28);
update auth.users set email_confirmed_at=now() where id in ('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000201');
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values('00000000-0000-4000-8000-000000000109','invitee.phase4b@example.invalid',now(),'{"display_name":"Phase Four Invitee"}');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000101","role":"authenticated"}',true);
select is((select count(*) from jsonb_array_elements(public.get_owner_team('10000000-0000-4000-8000-000000000001')->'members') item where item->>'role'='owner'),1::bigint,'owner reads same-tenant team DTO');
create temp table new_invitation as select public.create_team_invitation('10000000-0000-4000-8000-000000000001','  New.Member@Example.Invalid ') id;
grant select on new_invitation to authenticated,service_role;
select ok((select id is not null from new_invitation),'owner creates a staff invitation');
select is((select email_normalized from organization_invitations where id=(select id from new_invitation)),'new.member@example.invalid','email is normalized');
select is((select role from organization_invitations where id=(select id from new_invitation)),'staff','invitation cannot grant a privileged role');
select throws_ok($$select public.create_team_invitation('10000000-0000-4000-8000-000000000001','NEW.MEMBER@example.invalid')$$,'23505','active invitation exists','duplicate pending invitation is prevented');
select is(public.resend_team_invitation((select id from new_invitation)),'new.member@example.invalid','valid invitation resend succeeds');
select is(public.resend_team_invitation((select id from new_invitation)),'new.member@example.invalid','immediate resend retry is idempotent');
select is(public.revoke_team_invitation((select id from new_invitation)),'revoked','pending invitation revokes');
select is(public.revoke_team_invitation((select id from new_invitation)),'revoked','revocation retry is idempotent');
select throws_ok(format('select public.accept_team_invitation(%L)',(select id from new_invitation)),'42501','invitation not found','revoked invitation cannot be accepted');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000102","role":"authenticated"}',true);
select throws_ok($$select public.create_team_invitation('10000000-0000-4000-8000-000000000001','forged@example.invalid')$$,'42501','organization not found','staff cannot create invitations');
select throws_ok(format('select public.revoke_team_invitation(%L)',(select id from new_invitation)),'42501','organization not found','staff cannot revoke invitations');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000201","role":"authenticated"}',true);
select is((select count(*) from organization_invitations where organization_id='10000000-0000-4000-8000-000000000001'),0::bigint,'cross-tenant invitation reads fail closed');
select throws_ok(format('select public.resend_team_invitation(%L)',(select id from new_invitation)),'42501','organization not found','cross-tenant resend fails');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000101","role":"authenticated"}',true);
create temp table accepted_invitation as select public.create_team_invitation('10000000-0000-4000-8000-000000000001','invitee.phase4b@example.invalid') id;
grant select on accepted_invitation to authenticated,service_role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000102","role":"authenticated"}',true);
select throws_ok(format('select public.accept_team_invitation(%L)',(select id from accepted_invitation)),'42501','invitation not found','acceptance requires intended email');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000109","role":"authenticated"}',true);
create temp table accepted_membership as select public.accept_team_invitation((select id from accepted_invitation)) id;
grant select on accepted_membership to authenticated,service_role;
select ok((select id is not null from accepted_membership),'intended verified invitee accepts');
select is(public.accept_team_invitation((select id from accepted_invitation)),(select id from accepted_membership),'acceptance retry returns same membership');
select is((public.get_my_team_invitation((select id from accepted_invitation))->>'status'),'accepted','invitation records accepted state');
select is((select status from organization_memberships where id=(select id from accepted_membership)),'active','acceptance creates active membership');
select is((select status from staff_profiles where membership_id=(select id from accepted_membership)),'active','acceptance creates active staff profile');
reset role;set local role service_role;
insert into service_staff(organization_id,service_id,staff_profile_id,is_active)
select '10000000-0000-4000-8000-000000000001','12000000-0000-4000-8000-000000000101',id,true from staff_profiles where membership_id=(select id from accepted_membership);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000101","role":"authenticated"}',true);
select is(public.set_team_member_status((select id from accepted_membership),'inactive'),'inactive','owner deactivates same-tenant staff');
select is((select is_active from service_staff where staff_profile_id=(select id from staff_profiles where membership_id=(select id from accepted_membership))),false,'deactivation disables active service assignments');
select is((select is_active from service_staff where staff_profile_id='13000000-0000-4000-8000-000000000102'),true,'unrelated assignments are preserved');
select is(public.set_team_member_status((select id from accepted_membership),'inactive'),'inactive','deactivation retry is idempotent');
select throws_ok($$select public.set_team_member_status('11000000-0000-4000-8000-000000000101','inactive')$$,'23514','final active owner','final active owner is protected');
select throws_ok($$update organization_invitations set status='accepted',accepted_at=now() where id='18000000-0000-4000-8000-000000000105'$$,'42501',null,'direct invitation writes are denied by privileges');
select ok((select relrowsecurity from pg_class where oid='public.organization_invitations'::regclass),'invitation RLS remains enabled');
select is((select count(*) from audit_logs where action like 'team.%' and organization_id='10000000-0000-4000-8000-000000000001') >= 5,true,'effective team operations are audited');
select * from finish();
rollback;
